contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs driving the contract
    function run(bytes32 hash, uint pay) public payable {
        require(address(this).balance >= 1 ether);
        // precondition: only attempt to call lockInGuess with exactly 1 ether
        require(pay == 1 ether);

        // Ensure the call of lockInGuess either succeeds or we record revert
        bool reverted1;
        try c.lockInGuess{value: pay}(hash) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // Read observable state: c's balance and the public mapping getter for guesses
        // The compiler-generated getter for mapping(address=>Guess) is guesses(address)
        (uint gblock, bytes32 gguess) = c.guesses(address(this));
        uint bal = address(c).balance;

        // Now attempt a second lockInGuess to check it reverts when already locked
        bool reverted2;
        // Only try second call if first did not revert (only then mapping may be set)
        if (!reverted1) {
            try c.lockInGuess{value: pay}(hash) {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
        } else {
            // if first reverted, mimic that second is not attempted
            reverted2 = false;
        }

        // General rule asserted:
        // If the first lockInGuess succeeded (didn't revert), then (1) the stored block is non-zero,
        // (2) the stored guess equals the provided hash, (3) c's balance increased by exactly 1 ether,
        // and (4) a subsequent lockInGuess would revert (reverted2 == true).
        assert(
            reverted1 || (
                gblock != 0 &&
                gguess == hash &&
                bal >= 1 ether &&
                reverted2
            )
        );
    }

    // allow receiving ether
    receive() external payable {}
}

