contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to call lockInGuess (optionally) and then calls settle; it asserts that
    // if settle did not revert then the ether transferred to this test contract
    // is bounded by the previous balance of c (i.e., c cannot create ether).
    function run(bytes32 hash, uint pay) public payable {
        // allow only the canonical stake amount when attempting lockInGuess
        require(pay == 1 ether || pay == 0);
        // ensure this test contract has funds to send when pay==1 ether
        if (pay == 1 ether) require(address(this).balance >= 1 ether);

        // record balances before any interactions
        uint balC_before = address(c).balance;
        uint balMe_before = address(this).balance;

        // attempt to lock a guess if caller chose to send 1 ether
        bool lockedReverted;
        if (pay == 1 ether) {
            try c.lockInGuess{value: pay}(hash) {
                lockedReverted = false;
            } catch {
                lockedReverted = true;
            }
        } else {
            lockedReverted = true; // we didn't call lockInGuess
        }

        // attempt to settle (may revert). settle uses msg.sender == this contract.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint balC_after = address(c).balance;
        uint balMe_after = address(this).balance;

        // ASSERTION (general rule): if settle returned (did not revert), then the increase
        // in this contract's balance is at most the decrease in c's balance (i.e., c didn't
        // pay out more than it had). This forbids creation of ether by settle.
        assert(settleReverted || (balMe_after - balMe_before <= balC_before - balC_after));
    }

    receive() external payable {}
}

