contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept two parameters: a guess bytes32 and an amount to send when locking (must be 1 ether to succeed).
    // The function is payable so the test harness can fund this contract before calling run.
    function run(bytes32 guessHash, uint lockValue, uint settleTriggerPadding) public payable {
        require(lockValue <= 1 ether);
        // Ensure we have funds to send to c when locking
        require(address(this).balance >= lockValue);

        // Record contract balance before any interactions
        uint balBefore = address(c).balance;

        // Attempt to lock in a guess. This must be a top-level call.
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Immediately after lock attempt, read contract balance
        uint balAfterLock = address(c).balance;

        // We can only call settle if lockInGuess succeeded (otherwise there is no stored guess for this address)
        bool settleReverted;
        // To simulate calling settle in a later block, we simply call it; the prover will reason about blocks.
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint balFinal = address(c).balance;

        // Observables we can use in the assert: lockReverted, settleReverted, and balances.
        // General rule expressed as a single assert:
        // - If lockInGuess reverted, then balances should be unchanged (no funds transferred to c).
        // - If lockInGuess succeeded and we sent exactly 1 ether, c's balance increased by 1 after lock.
        // - If settle succeeded (did not revert) then either c paid out 2 ether (balance decreased by 2)
        //   or c did not pay out (balance stayed the same or only changed by prior lock). The payout of 2
        //   ether can only occur if we previously successfully locked with 1 ether; otherwise it cannot.
        assert(
            // Case A: lock reverted -> no change in contract balance
            (lockReverted && balAfterLock == balBefore && balFinal == balBefore)
            ||
            // Case B: lock succeeded with exactly 1 ether sent
            (!lockReverted && lockValue == 1 ether && balAfterLock == balBefore + 1 ether && (
                // If settle reverted then final balance equals after lock (no payout)
                (settleReverted && balFinal == balAfterLock)
                ||
                // If settle succeeded then final balance is either reduced by 2 (payout) or unchanged
                (!settleReverted && (balFinal + 2 ether == balAfterLock || balFinal == balAfterLock))
            ))
            ||
            // Case C: lock succeeded but with wrong value (not 1 ether) -> contract shouldn't accept it, so treat as no change
            (!lockReverted && lockValue != 1 ether && balAfterLock == balBefore && balFinal == balBefore)
        );
    }

    // Allow receiving Ether when settle sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: guess hash and amount to send when calling lockInGuess
    function run(bytes32 guessHash, uint lockValue) public payable {
        // allow any lockValue provided funds are available
        require(address(this).balance >= lockValue);

        // observe contract balance and stored block for this tester before the call
        uint balBefore = address(c).balance;
        // c.guesses is not public, but guesses mapping elements are not accessible; however C does not expose a getter for guesses.
        // The only public observable related to a successful lock is the contract balance and that subsequent settle requires guesses[msg.sender].block != 0.
        // We instead observe whether settle would revert immediately (which indicates no stored guess block for this address) by trying settle now.
        bool settleRevertedBefore;
        try c.settle() {
            settleRevertedBefore = false;
        } catch {
            settleRevertedBefore = true;
        }

        // Attempt to lock in the guess; must be a top-level call
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint balAfter = address(c).balance;

        // After attempting lock, try calling settle to detect whether a block was recorded (settle reverts if none or if called too early)
        bool settleRevertedAfter;
        try c.settle() {
            settleRevertedAfter = false;
        } catch {
            settleRevertedAfter = true;
        }

        // General invariant (single assert):
        // - If lockInGuess succeeded and exactly 1 ether was sent, the contract balance increased by exactly 1 ether and before we couldn't settle but afterward either we still can't settle (if called too early) or we can (meaning a block was set). At least the balance change must reflect the 1 ether deposit.
        // - If lockInGuess reverted then the contract balance is unchanged and the ability to settle did not improve (if settle was callable before it should remain callable; if it wasn't callable before it should remain not callable).
        assert(
            // Case A: lock reverted -> no balance change and settle revert-status unchanged
            (lockReverted && balAfter == balBefore && settleRevertedAfter == settleRevertedBefore)
            ||
            // Case B: lock succeeded with exactly 1 ether -> balance increased by 1 and settle became no more permissive than before (it may still revert if called too early, but we at least deposited funds)
            (!lockReverted && lockValue == 1 ether && balAfter == balBefore + 1 ether)
        );
    }

    // allow receiving Ether when settle pays out
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // we accept parameters to drive lockInGuess and settle
    // guessHash: bytes32 to lock in, lockValue: must be 1 ether to succeed (we allow other values to test revert behavior)
    // sendForLock: amount to send to lockInGuess call
    function run(bytes32 guessHash, uint sendForLock) public payable {
        require(address(this).balance >= sendForLock, "insufficient balance for test");

        // Try to lock in a guess; capture whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: sendForLock}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Read observable state after lock attempt: contract balance and the Guess struct via public getter
        uint balAfterLock = address(c).balance;
        (uint storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // Now attempt to call settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // After settle attempt, read observable state again
        uint balAfterSettle = address(c).balance;
        (uint storedBlockAfter, bytes32 storedGuessAfter) = c.guesses(address(this));

        // General rule asserted:
        // 1) If settle did not revert, then the stored block for this tester must be cleared (be 0).
        // 2) In any case, the contract's balance decreased by at most 2 ether due to the settle call
        //    (i.e., balAfterSettle >= balAfterLock - 2 ether). This ensures settle never pays out >2 ether.
        assert((!settleReverted ? storedBlockAfter == 0 : true) && (balAfterSettle + 2 ether >= balAfterLock));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Provide parameters to attempt a lock and then call settle.
    // sendForLock is used as value for lockInGuess; it may be any amount.
    function run(bytes32 guessHash, uint sendForLock) public payable {
        // ensure this test contract has enough balance to send
        require(address(this).balance >= sendForLock, "insufficient balance for test");

        // Record contract balance before any calls
        uint balBefore = address(c).balance;

        // Attempt lockInGuess and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: sendForLock}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Now attempt to call settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Read contract balance after settle attempt
        uint balAfter = address(c).balance;

        // General rule asserted:
        // If settle did not revert then (1) the contract's balance decreased by at most 2 ether
        // (i.e., settle pays out at most 2 ether), and (2) the caller's stored guess must have been cleared.
        // We cannot access internal storage directly, but we can observe that if settle succeeded (did not revert)
        // then either it paid out at most 2 ether (balance check) and the guess-slot for this caller must be cleared
        // because further calls to settle immediately would revert due to guesses[msg.sender].block == 0.

        // To observe the clearing effect, attempt a second settle call: if the first settle succeeded then
        // the second settle must revert (because block == 0). If the first settle reverted, we make no assumption.
        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }

        // Assert the general rule: if the first settle did not revert then (a) balance decreased by at most 2 ether
        // and (b) the second settle must revert (meaning the stored guess was cleared).
        assert(
            settleReverted || (
                // balance decreased by at most 2 ether
                balAfter + 2 ether >= balBefore &&
                // second settle reverted, indicating stored guess cleared
                secondSettleReverted
            )
        );
    }

    // allow this test contract to receive ether for funding sendForLock
    receive() external payable {}
}
